#include "apex/enemy.hpp"
#include "apex/log.hpp"
namespace apex {namespace {
bool sameModel(const EnemyOptions& a,const EnemyOptions& b){return a.modelPath==b.modelPath&&a.preferCuda==b.preferCuda;}
}
EnemyService::~EnemyService(){stop();}
void EnemyService::stop(){{std::lock_guard<std::mutex> lock(mutex_);stop_=true;pending_.reset();}wake_.notify_all();if(worker_.joinable())worker_.join();}
void EnemyService::beginSource(){std::lock_guard<std::mutex> lock(mutex_);++generation_;pending_.reset();lastSequence_=0;state_.latest=EnemyObservation{};state_.analyzedFrame.reset();state_.completed=0;state_.status="waiting_for_frame";}
EnemySnapshot EnemyService::snapshot()const{std::lock_guard<std::mutex> lock(mutex_);return state_;}
void EnemyService::submit(std::shared_ptr<const CapturedFrame> frame,const EnemyOptions& o,const std::string& source,bool force){if(!frame)return;if(o.modelPath.empty())throw std::runtime_error("Choose your trained enemy .onnx model first");std::lock_guard<std::mutex> lock(mutex_);auto now=std::chrono::steady_clock::now();bool changed=!configured_||!sameModel(o,last_)||o.confidence!=last_.confidence||o.iou!=last_.iou;if(changed){++generation_;pending_.reset();lastSequence_=0;last_=o;configured_=true;state_.latest=EnemyObservation{};state_.analyzedFrame.reset();}if(!force&&!changed&&(frame->sequence==lastSequence_||std::chrono::duration_cast<std::chrono::milliseconds>(now-submitted_).count()<o.intervalMs))return;if(!worker_.joinable()){stop_=false;worker_=std::thread([this]{run();});}lastSequence_=frame->sequence;submitted_=now;pending_=Job{std::move(frame),o,source,generation_};wake_.notify_one();}
void EnemyService::run()noexcept{std::unique_ptr<EnemyDetector> detector;EnemyOptions active;while(true){Job job;{std::unique_lock<std::mutex> lock(mutex_);wake_.wait(lock,[&]{return stop_||pending_.has_value();});if(stop_)break;job=std::move(*pending_);pending_.reset();state_.busy=true;state_.status="running";}try{if(!detector||!sameModel(active,job.options)){detector=makeEnemyDetector(job.options);active=job.options;}auto result=detector->run(*job.frame,job.options);result.source=job.source;std::lock_guard<std::mutex> lock(mutex_);if(job.generation==generation_&&!stop_){state_.latest=std::move(result);state_.analyzedFrame=job.frame;++state_.completed;state_.status="ready";state_.message=state_.latest.message;}}catch(const std::exception& e){Log::write("WARN",std::string("Enemy detector: ")+e.what());std::lock_guard<std::mutex> lock(mutex_);if(job.generation==generation_){state_.status="unavailable";state_.message=e.what();}detector.reset();}{std::lock_guard<std::mutex> lock(mutex_);state_.busy=false;}}}
}
